-- Explicit identity values do not advance their owned sequences.
DO $$
DECLARE
    table_name TEXT;
    column_name TEXT;
    sequence_name TEXT;
BEGIN
    FOR table_name, column_name, sequence_name IN
        SELECT columns.table_name,
               columns.column_name,
               pg_get_serial_sequence(format('%I.%I', columns.table_schema, columns.table_name), columns.column_name)
        FROM information_schema.columns AS columns
        WHERE columns.table_schema = 'world'
    LOOP
        IF sequence_name IS NOT NULL THEN
            EXECUTE format(
                'SELECT setval(%L, COALESCE(MAX(%I), 1), MAX(%I) IS NOT NULL) FROM %I.%I',
                sequence_name, column_name, column_name, 'world',
                table_name
            );
        END IF;
    END LOOP;
END $$;
